std::string OrcaWorkspaceAdapter::slice_refusal() const
{
    PartPlateList&    plates = m_plater.get_partplate_list();
    PartPlate&        plate  = *plates.get_curr_plate();
    const std::string name   = plate_name(plate, plates.get_curr_plate_index());
    if (plate.empty())
        return name + " has nothing on it to slice.";
    Print&                      print = plates.get_current_fff_print();
    StringObjectException       warning;
    const StringObjectException error = validate_print(m_plater, print, warning);
    if (!error.string.empty())
        return boost::algorithm::trim_copy(error.string) + bed_type_advice(error, print);
    if (!plate.can_slice() && !plate.is_apply_result_invalid())
        return "An object on " + name + " is partly outside the printable area. Move it onto the plate, or off it.";
    BOOST_LOG_TRIVIAL(warning) << "JusPrin: Orca did not slice " << name << " and its checks give no reason";
    return "OrcaSlicer did not slice " + name + " and gave no reason.";
}

std::string OrcaWorkspaceAdapter::slice_failure(PlateId plate) const
{
    wxASSERT(wxIsMainThread());
    if (plate.session() != m_session)
        return {};
    if (const auto found = m_slice_failures.find(plate.value()); found != m_slice_failures.end())
        return found->second;
    // A run of every plate stops at the first plate Orca will not slice, and
    // leaves it the current one.
    if (m_plater.get_partplate_list().get_curr_plate()->id().id == plate.value())
        return slice_refusal();
    return {};
}

void OrcaWorkspaceAdapter::on_process_completed(SlicingProcessCompletedEvent& event)
{
    event.Skip();
    // Bound after Plater's own handler, so this runs first, while the plate
    // the run was for is still the current one.
    const std::uint64_t plate = m_plater.get_partplate_list().get_curr_plate()->id().id;
    if (event.error())
        m_slice_failures[plate] = boost::algorithm::trim_copy(event.format_error_message().first);
    else if (event.cancelled())
        m_slice_failures[plate] = "The slice was stopped before it finished.";
    else
        m_slice_failures.erase(plate);
}

