// Orca refuses a plate type a filament has no bed temperature for (0), and
// its words name neither the setting nor a plate type that would do. Both are
// read from the option Print::validate reads, so they cannot disagree with it.
std::string bed_type_advice(const StringObjectException& error, const Print& print)
{
    if (error.type != STRING_EXCEPT_FILAMENT_NOT_MATCH_BED_TYPE || error.params.size() < 3)
        return {};
    const int          filament = std::atoi(error.params[2].c_str()) - 1;
    const PrintConfig& config   = print.config();
    std::string advice = " The setting is the filament's " + get_bed_temp_key(config.curr_bed_type) + ", which is 0.";
    const PresetBundle&            bundle  = *wxGetApp().preset_bundle;
    const std::vector<std::string> offered = supported_plates(bundle.printers, bundle.printers.get_edited_preset());
    std::string                    plates;
    for (int type = btPC; type < btCount; ++type) {
        const std::string label        = plate_label(BedType(type));
        const auto*       temperatures = config.option<ConfigOptionInts>(get_bed_temp_key(BedType(type)));
        if (std::find(offered.begin(), offered.end(), label) != offered.end() && temperatures != nullptr &&
            temperatures->get_at(filament) > 0)
            plates += (plates.empty() ? "" : ", ") + label;
    }
    if (!plates.empty())
        advice += " Plate types this printer offers that it has a bed temperature for: " + plates + ".";
    return advice;
}
