// Seen in live runs: a filament with no bed temperature for the plate type
// made Orca refuse the slice, the call reported it started, and a second call
// with wait never returned.
TEST_CASE("a plate Orca will not slice fails the call with Orca's reason, waiting or not", "[tools][slicing]")
{
    Harness h;
    const auto& registry = ToolRegistry::instance();
    const std::string reason = "Plate 1: Cool Plate is not suggested to be used to print filament 1 (Bambu PETG HF). "
                               "The setting is the filament's cool_plate_temp, which is 0.";
    h.workspace.slice_refusal_for_testing = reason;

    for (const char* arguments : {R"({"wait":true})", R"({"preempt":true,"wait":true})", "{}"}) {
        DYNAMIC_SECTION("slice_start " << arguments)
        {
            const std::string action = h.coordinator.propose({"slice_start", arguments}, "m-1").action_id;
            h.pump_to_completion(action, 20);
            const ToolActivity done = *h.coordinator.find(action);
            REQUIRE(done.state == ToolState::Failed);
            CHECK(done.error->code == "unavailable_operation");
            CHECK(done.error->message == reason);
            CHECK(h.workspace.slice_starts == 0);
        }
    }

    // Once the setup is one Orca will slice, the same call goes through.
    h.workspace.slice_refusal_for_testing.clear();
    const std::string action = h.coordinator.propose({"slice_start", R"({"wait":true})"}, "m-2").action_id;
    h.coordinator.pump();
    h.workspace.finish_slice_for_testing(true);
    h.pump_to_completion(action, 20);
    REQUIRE(h.coordinator.find(action)->state == ToolState::Succeeded);
    CHECK(registry.validate_output(*registry.find("slice_start"), json::parse(h.coordinator.find(action)->result_json)));
}

TEST_CASE("a waited-for run that ends without slicing the plate fails and says why", "[tools][slicing]")
{
    Harness h;
    const auto start = [&h] {
        const std::string action = h.coordinator.propose({"slice_start", R"({"wait":true})"}, "m-1").action_id;
        h.coordinator.pump();
        REQUIRE(h.coordinator.find(action)->state == ToolState::Running);
        return action;
    };

    const std::string stopped = start();
    h.workspace.finish_slice_for_testing(false, "The slice was stopped before it finished.");
    h.pump_to_completion(stopped, 20);
    REQUIRE(h.coordinator.find(stopped)->state == ToolState::Failed);
    CHECK(h.coordinator.find(stopped)->error->code == "unavailable_operation");
    CHECK(h.coordinator.find(stopped)->error->message == "The slice was stopped before it finished.");

    // Orca gave no reason: the call still ends, and says which plate.
    const std::string silent = start();
    h.workspace.finish_slice_for_testing(false);
    h.pump_to_completion(silent, 20);
    REQUIRE(h.coordinator.find(silent)->state == ToolState::Failed);
    CHECK(h.coordinator.find(silent)->error->message == "The slice ended without slicing Plate 1.");
}

