// Opt-in --slice-refused. See the mode comment at the top of this file.
void begin_slice_refused()
{
    auto* workspace = installed_shell()->workspace();
    Workspace::LoadReport            report;
    std::vector<Workspace::ObjectId> added;
    Workspace::ImportRequest         import;
    import.path = std::string(JUSPRIN_SOURCE_DIR) + "/tests/data/jusprin/tee_with_hole.stl";
    check(workspace->import_objects(import, report, added).succeeded() && added.size() == 1, "refused_fixture_imported");
    check(refused_setup("Smooth Cool Plate"), "refused_petg_on_the_cool_plate");
    const auto plate = workspace->snapshot().active_plate;
    check(plate.has_value(), "refused_fixture_has_a_plate");
    if (!plate) {
        finish();
        return;
    }

    // Straight after the setup, the soonest a tool call can follow it, and
    // again: each form fails at once, and says which setting and which
    // plate types would do.
    const std::string plate_id = std::to_string(plate->value());
    const std::pair<std::string, std::string> calls[] = {
        {R"({"wait":true})", "wait"},
        {R"({"preempt":true,"wait":true})", "preempt_wait"},
        {"{}", "no_wait"},
        {nlohmann::json{{"plateId", plate_id}, {"wait", true}}.dump(), "plate_wait"},
    };
    for (const auto& [arguments, name] : calls) {
        const Agent::ToolActivity done = run_tool_now("slice_start", arguments);
        const std::string message = done.error ? done.error->message : done.result_json;
        std::cout << "HARNESS REFUSED slice_start " << arguments << " state " << int(done.state) << ": " << message << std::endl;
        check(done.state == Agent::ToolState::Failed, "refused_" + name + "_fails");
        check(message.find("cool_plate_temp") != std::string::npos && message.find("Textured PEI Plate") != std::string::npos,
              "refused_" + name + "_says_which_setting_and_plate");
        const auto snapshot = workspace->snapshot();
        check(!snapshot.slicing.running && !snapshot.plates.front().sliced, "refused_" + name + "_slices_nothing");
    }

    check(refused_setup("Textured PEI Plate"), "refused_textured_plate_chosen");
    const std::string sliced = propose_tool("slice_start", R"({"wait":true})");
    wait_until([sliced] { return tool_ended(sliced); }, "refused_textured_plate_slice_ends",
               [self = shared_from_this(), sliced] {
                   const Agent::ToolActivity& done = *agent_tools().find(sliced);
                   self->check(done.state == Agent::ToolState::Succeeded &&
                                   nlohmann::json::parse(done.result_json).value("finished", false),
                               "refused_textured_plate_slices");
                   self->verify_waited_slice_stopped();
               },
               [] { installed_shell()->agent_pane()->web_view().host().pump_tools(); });
}

// A run the call waits for that is stopped ends the call, saying so.
void verify_waited_slice_stopped()
{
    auto* workspace = installed_shell()->workspace();
    const Workspace::SettingsPatch finer{{{"layer_height", "0.12"}}};
    Workspace::SettingsPreview     applied;
    workspace->apply_settings(finer, Workspace::previewed_changes(workspace->preview_settings(finer)), applied);
    const std::string action = propose_tool("slice_start", R"({"wait":true})");
    installed_shell()->agent_pane()->web_view().host().pump_tools();
    check(workspace->snapshot().slicing.running, "refused_waited_slice_running");
    bool stopped = false;
    check(workspace->cancel_slice(stopped).succeeded() && stopped, "refused_waited_slice_cancelled");
    wait_until([action] { return tool_ended(action); }, "refused_stopped_slice_call_ends",
               [self = shared_from_this(), action] {
                   const Agent::ToolActivity& done = *agent_tools().find(action);
                   const std::string message = done.error ? done.error->message : done.result_json;
                   std::cout << "HARNESS REFUSED stopped slice: " << message << std::endl;
                   self->check(done.state == Agent::ToolState::Failed && message.find("stopped") != std::string::npos,
                               "refused_stopped_slice_says_so");
                   self->check(self->m_plater->new_project(true, true) != wxID_CANCEL, "refused_teardown_project");
                   self->finish();
               },
               [] { installed_shell()->agent_pane()->web_view().host().pump_tools(); });
}

// The fixture's setup with one plate type, as printer_setup applies it.
bool refused_setup(const std::string& plate_type)
{
    Workspace::PrinterSetupRequest request;
    request.printer_preset        = kSetupFixturePrinter;
    request.plate_type            = plate_type;
    request.filament_presets      = std::vector<std::string>{"Bambu PETG HF @BBL X1C"};
    request.discard_unsaved_edits = true;
    Workspace::PrinterSetupPreview applied;
    const auto result = installed_shell()->workspace()->apply_printer_setup(request, applied);
    if (!result.succeeded())
        std::cout << "HARNESS REFUSED setup " << plate_type << ": " << result.message << std::endl;
    return result.succeeded() && installed_shell()->workspace()->configured_printer().plate_type == plate_type;
}

static Agent::ToolExecutionCoordinator& agent_tools() { return installed_shell()->agent_pane()->web_view().host().tools(); }
static bool tool_ended(const std::string& action) { return Agent::tool_state_terminal(agent_tools().find(action)->state); }
static std::string propose_tool(const std::string& tool, const std::string& arguments)
{
    return agent_tools().propose({tool, arguments}, "slice-refused").action_id;
}

// A call pumped to its end without the event loop: what the tool does
// before it returns, with no run to wait for. A call still running after
// that is returned running.
static Agent::ToolActivity run_tool_now(const std::string& tool, const std::string& arguments)
{
    const std::string action = propose_tool(tool, arguments);
    for (int tick = 0; tick < 200 && !tool_ended(action); ++tick)
        installed_shell()->agent_pane()->web_view().host().pump_tools();
    return *agent_tools().find(action);
}

